        countdown.value -= 1

        if (countdown.value <= 0) {
          if (interval) {
            clearInterval(interval)
          }

          window.location.reload()
        }
      }, 1000)
    }

    onUnmounted(() => {
      if (interval) {
        clearInterval(interval)
      }
    })

    function retry(): void {
      window.location.reload()
    }
    </script>

    <template>
      <main v-if="error.statusCode === 429">
        <h1>Too many requests</h1>

        <p v-if="countdown > 0">
          Retrying in {{ countdown }} seconds…
        </p>

        <button type="button" @click="retry">
          Retry now
        </button>
      </main>
    </template>


There is nothing else the user needs to do. When the request window resets, the page reloads automatically.

